INSERT INTO `Product` VALUES ('cmq3uzhgd0002pv1pmv9tkdxv','Scarlet Rose Heart Cake','scarlet-rose-heart-cake-mq3uzhgc','Designed in a charming heart shape, this cake is crowned with intricate scarlet red buttercream rosettes that create the look of a blooming rose garden. Delicate pearl accents and golden beads add a touch of elegance, while the crisp white base beautifully highlights the vibrant floral design. A heartfelt creation made to celebrate enduring love and cherished anniversaries.',NULL,599,NULL,'[\"https://res.cloudinary.com/dvw9o0f8z/image/upload/v1780841294/blissbakery/products/1780841294210-gjlte0.jpg\"]',0,0,0,1,NULL,'[\"anniversary\"]','[\"heart-shape\",\"1-tier-\"]',NULL,'cmq2aide00001pvoou1f9tqu7','2026-06-07 14:09:53.437','2026-06-07 21:54:12.746','[\"Chocochips\",\"Hazelnut\",\"Nutella\",\"Belgian Chocolate\",\"Almond Truffle\",\"Truffle Dutch\",\"Butterscotch\",\"Salted Caramel\",\"Red Velvet\",\"Pineapple\",\"Blueberry\",\"Strawberry\",\"Kesar Pista\",\"Rose\"]','[]',300,149,'[{\"name\":\"Chocochips\",\"price500g\":550},{\"name\":\"Hazelnut\",\"price500g\":600},{\"name\":\"Nutella\",\"price500g\":600},{\"name\":\"Belgian Chocolate\",\"price500g\":650},{\"name\":\"Almond Truffle\",\"price500g\":650},{\"name\":\"Truffle Dutch\",\"price500g\":600},{\"name\":\"Butterscotch\",\"price500g\":550},{\"name\":\"Salted Caramel\",\"price500g\":650},{\"name\":\"Red Velvet\",\"price500g\":600},{\"name\":\"Pineapple\",\"price500g\":450},{\"name\":\"Blueberry\",\"price500g\":450},{\"name\":\"Strawberry\",\"price500g\":450},{\"name\":\"Kesar Pista\",\"price500g\":650},{\"name\":\"Rose\",\"price500g\":550}]','CUSTOM','Blueberry'),('cmq3v1xc7000epv1p9e5q9pbx','Blush Love Bloom Cake','blush-love-bloom-cake-mq3v1xc6','Finished in a soft blush pink shade, this heart-shaped cake features an elegant border of handcrafted buttercream roses and delicate ruffle petals. The golden \"Love\" topper adds a romantic touch, while the floral heart design creates a graceful and timeless centerpiece. A beautifully styled cake that speaks the language of love through every detail.',NULL,599,NULL,'[\"https://res.cloudinary.com/dvw9o0f8z/image/upload/v1780841441/blissbakery/products/1780841440632-4sfudp.jpg\"]',0,0,0,1,NULL,'[\"birthday\",\"anniversary\",\"festival\"]','[\"her\",\"heart-shape\",\"1-tier-\",\"valentine-day\"]',NULL,'cmq2aide00001pvoou1f9tqu7','2026-06-07 14:11:47.335','2026-06-07 21:47:00.910','[\"Chocochips\",\"Hazelnut\",\"Nutella\",\"Belgian Chocolate\",\"Almond Truffle\",\"Truffle Dutch\",\"Butterscotch\",\"Salted Caramel\",\"Red Velvet\",\"Pineapple\",\"Blueberry\",\"Strawberry\",\"Kesar Pista\",\"Rose\"]','[]',300,149,'[{\"name\":\"Chocochips\",\"price500g\":550},{\"name\":\"Hazelnut\",\"price500g\":600},{\"name\":\"Nutella\",\"price500g\":600},{\"name\":\"Belgian Chocolate\",\"price500g\":650},{\"name\":\"Almond Truffle\",\"price500g\":650},{\"name\":\"Truffle Dutch\",\"price500g\":600},{\"name\":\"Butterscotch\",\"price500g\":550},{\"name\":\"Salted Caramel\",\"price500g\":650},{\"name\":\"Red Velvet\",\"price500g\":600},{\"name\":\"Pineapple\",\"price500g\":450},{\"name\":\"Blueberry\",\"price500g\":450},{\"name\":\"Strawberry\",\"price500g\":450},{\"name\":\"Kesar Pista\",\"price500g\":650},{\"name\":\"Rose\",\"price500g\":550}]','CUSTOM','Blueberry'),('cmq3v4tbd000qpv1p3v19mxui','Ruby Pearl Heart Cake','ruby-pearl-heart-cake-mq3v4tbb','Wrapped in a rich ruby-red finish, this heart-shaped cake is beautifully adorned with elegant pearl garlands that drape gracefully around its sides. Delicate piped borders frame the design, creating a classic vintage-inspired look. The striking contrast of red and white gives this cake a bold yet sophisticated charm that instantly captures attention.',NULL,599,NULL,'[\"https://res.cloudinary.com/dvw9o0f8z/image/upload/v1780841533/blissbakery/products/1780841533191-xju39t.jpg\"]',0,0,0,1,NULL,'[\"birthday\"]','[\"her\"]',NULL,'cmq2aide00001pvoou1f9tqu7','2026-06-07 14:14:02.089','2026-